<?php if(!isset($config))$config=require __DIR__.'/../config/config.php'; ?><style>:root{--menu-w:268px;--menu-line:#23344d;--menu-muted:#8ea2bb}body.has-global-menu{padding-left:var(--menu-w)!important;transition:padding-left .2s ease}body.has-global-menu.menu-page-collapsed{padding-left:0!important}.global-menu{position:fixed;z-index:50;inset:0 auto 0 0;width:var(--menu-w);padding:18px 14px;background:linear-gradient(180deg,#0b1321,#080d15);border-right:1px solid var(--menu-line);display:flex;flex-direction:column;gap:16px;transition:transform .2s ease}.global-menu.is-collapsed{transform:translateX(-100%)}.global-menu__brand{display:flex;align-items:center;gap:10px;padding:4px 8px}.global-menu__logo{width:36px;height:36px;display:grid;place-items:center;border-radius:11px;background:linear-gradient(135deg,#6da7ff,#7669e8);font-weight:900;color:white}.global-menu__brand strong{display:block;color:#fff;font-size:14px}.global-menu__brand small{display:block;color:var(--menu-muted);font-size:10px;margin-top:2px}.global-menu__toggle{position:absolute;right:-15px;top:20px;width:30px;height:30px;border-radius:50%;border:1px solid var(--menu-line);background:#14243a;color:white;cursor:pointer}.global-menu__new{width:100%;padding:11px 12px;border:1px solid #31517e;border-radius:9px;background:#132844;color:#e4f0ff;text-align:left;font-weight:700;cursor:pointer}.global-menu nav{display:grid;gap:4px}.global-menu a{padding:10px 11px;border-radius:8px;color:var(--menu-muted);text-decoration:none;font-size:13px}.global-menu a:hover{background:#15243a;color:#fff}.global-menu__usage{margin-top:auto;border:1px solid var(--menu-line);border-radius:11px;padding:12px;color:var(--menu-muted);font-size:11px}.global-menu__usage b{display:block;color:#fff;margin-bottom:5px}.global-menu__bar{height:5px;background:#17253a;border-radius:99px;overflow:hidden;margin-top:8px}.global-menu__bar i{display:block;height:100%;width:0;background:linear-gradient(90deg,#6da7ff,#8ee0ad);transition:width