Mobile(localStorage.getItem('zystem_menu_open')==='1');fetch('../api/usage.php').then(r=>r.json()).then(d=>{if(!d.ok)throw Error();const u=document.querySelector('#menuUsage');u.querySelector('span').textContent=`${d.files} arquivos · ${d.human_size}`;u.querySelector('i').style.width=Math.min(100,d.percent||0)+'%'}).catch(()=>document.querySelector('#menuUsage span').textContent='Uso indisponível')})();</script>
